function sendBlocked(log, cust, camp, seq) {
  let started = false, fails = 0;
  for (const l of log) {
    if (s(l.customer_id) !== cust || s(l.campaign_id) !== camp || s(l.email_sequence) !== seq) continue;
    if (l.event_type === 'EMAIL_SEND_STARTED') started = true;
    else if (l.event_type === 'EMAIL_FAILED') { started = false; fails++; }
  }
  return { blocked: started, fails };
}

const S = $('Get Settings').first().json.settings;
const rows = $('Read Customers').all().map(i => i.json).filter(r => s(r.customer_id) || s(r.email));
const log = $input.all().map(i => i.json).filter(l => l.event_id);
const camp = s(S.campaign_id);
const today = todayStr();
const idCount = {};
rows.forEach(r => { const id = s(r.customer_id); if (id) idCount[id] = (idCount[id] || 0) + 1; });
let cr = null;
try { cr = require('crypto'); } catch (e) { cr = null; }
const token = () => cr ? cr.randomBytes(16).toString('hex') : Array.from({ length: 32 }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const out = [];
for (const r of rows) {
  const id = s(r.customer_id);
  if (!id || idCount[id] !== 1) continue;
  if (!isEmail(r.email)) continue;
  if (!isDate(s(r.last_service_date))) continue;
  if (s(r.consent_status) !== 'OPTED_IN') continue;
  if (s(r.booking_status) === 'BOOKED') continue;
  const cs = s(r.campaign_status) || 'NOT_STARTED';
  if (!['NOT_STARTED', 'ELIGIBLE'].includes(cs)) continue;
  if (daysBetween(s(r.last_service_date), today) <= S.reactivation_days) continue;
  const b = sendBlocked(log, id, camp, 'INITIAL');
  if (b.blocked || b.fails >= 3) continue;
  out.push(r);
}
out.sort((a, b) => (s(a.last_service_date) < s(b.last_service_date) ? -1 : 1));
const cap = Math.max(0, Number(S.max_emails_per_run) || 0);
const now = nowIso();
return out.slice(0, cap).map(r => ({ json: {
  customer_id: s(r.customer_id),
  customer_status: 'INACTIVE',
  campaign_status: 'ELIGIBLE',
  unsubscribe_token: s(r.unsubscribe_token) || token(),
  updated_at: now } }));

